reference.cpp:
#include <cstdio>
#include <vector>
#include <string>
#include <queue>
#include <sstream>
#include <iostream>

struct Node {
    long long v;
    Node *l = nullptr, *r = nullptr;
};

Node* buildTree(const std::vector<std::string> &t) {
    if (t.empty() || t[0] == "null") return nullptr;
    Node *root = new Node{std::stoll(t[0])};
    std::queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < t.size()) {
        Node *cur = q.front(); q.pop();
        if (i < t.size()) {
            if (t[i] != "null") { cur->l = new Node{std::stoll(t[i])}; q.push(cur->l); }
            ++i;
        }
        if (i < t.size()) {
            if (t[i] != "null") { cur->r = new Node{std::stoll(t[i])}; q.push(cur->r); }
            ++i;
        }
    }
    return root;
}

bool dfs(Node *n, long long rest) {
    if (!n) return false;
    rest -= n->v;
    if (!n->l && !n->r) return rest == 0;   // 必须是叶子
    return dfs(n->l, rest) || dfs(n->r, rest);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    long long target;
    scanf("%lld", &target);

    std::istringstream iss(line);
    std::vector<std::string> tok;
    std::string t;
    while (iss >> t) tok.push_back(t);
    if (tok.empty()) tok.push_back("null");

    printf("%s\n", dfs(buildTree(tok), target) ? "YES" : "NO");
    return 0;
}
